const currentPlaces = $json.places || [];
const nextPageToken = $json.nextPageToken || null;
const previous = $('Init Pagination').item.json.allPlaces || [];

const merged = [...previous, ...currentPlaces];

// Deduplicate by place_id
const seen = new Set();
const deduped = merged.filter(p => {
  if (seen.has(p.id)) return false;
  seen.add(p.id);
  return true;
});

return [{
  json: {
    ...$('Build Search Query').item.json,
    allPlaces: deduped,
    pageToken: nextPageToken,
    hasMore: !!nextPageToken && deduped.length < 60
  }
}];

const places = $json.allPlaces || [];
const filters = $('Build Search Query').item.json;
const websiteFilter = filters.websiteFilter || 'both';

// Start with user-requested filters
let minRating = parseFloat(filters.minRating) || 0;
let maxReviews = parseInt(filters.maxReviews) || 9999;
let minReviews = parseInt(filters.minReviews) || 0;

function passesWebsiteFilter(place, filterType) {
  const hasWebsite = !!(place.websiteUri && place.websiteUri.trim() !== '');
  if (filterType === 'no_website') return !hasWebsite;
  if (filterType === 'has_website') return hasWebsite;
  return true;
}

function scoreAndFilter(placeList, minR, maxRev, minRev, webFilter) {
  const results = [];

  for (const place of placeList) {
    const reviewCount = place.userRatingCount || 0;
    const rating = place.rating || 0;

    // Apply rating filter
    if (minR > 0 && rating < minR) continue;

    // Apply review count filters
    if (reviewCount > maxRev) continue;
    if (reviewCount < minRev) continue;

    // Apply website filter
    if (!passesWebsiteFilter(place, webFilter)) continue;

    // Score it
    let tier = 4;
    if (reviewCount <= 20) tier = 1;
    else if (reviewCount <= 200) tier = 2;
    else if (reviewCount >= 1000 && rating < 4.5) tier = 3;

    results.push({
      place_id: place.id || '',
      name: place.displayName?.text || 'Unknown',
      address: place.formattedAddress || 'Unknown',
      phone: place.internationalPhoneNumber || 'Not listed',
      website: place.websiteUri || null,
      has_website: !!(place.websiteUri && place.websiteUri.trim() !== ''),
      rating: rating,
      review_count: reviewCount,
      google_maps_url: place.googleMapsUri || '',
      business_status: place.businessStatus || 'Unknown',
      category: place.types ? place.types[0] : 'Unknown',
      priority_tier: tier
    });
  }

  return results;
}

// Try with user filters first
let scored = scoreAndFilter(places, minRating, maxReviews, minReviews, websiteFilter);

// If zero results — progressively relax filters
// Step 1: relax review count limits
if (scored.length === 0 && (maxReviews < 9999 || minReviews > 0)) {
  scored = scoreAndFilter(places, minRating, 9999, 0, websiteFilter);
}

// Step 2: relax rating filter
if (scored.length === 0 && minRating > 0) {
  scored = scoreAndFilter(places, 0, 9999, 0, websiteFilter);
}

// Step 3: relax website filter too
if (scored.length === 0 && websiteFilter !== 'both') {
  scored = scoreAndFilter(places, 0, 9999, 0, 'both');
}

// Step 4: return everything with no filters at all
if (scored.length === 0) {
  for (const place of places) {
    const reviewCount = place.userRatingCount || 0;
    const rating = place.rating || 0;
    let tier = 4;
    if (reviewCount <= 20) tier = 1;
    else if (reviewCount <= 200) tier = 2;
    else if (reviewCount >= 1000 && rating < 4.5) tier = 3;

    scored.push({
      place_id: place.id || '',
      name: place.displayName?.text || 'Unknown',
      address: place.formattedAddress || 'Unknown',
      phone: place.internationalPhoneNumber || 'Not listed',
      website: place.websiteUri || null,
      has_website: !!(place.websiteUri && place.websiteUri.trim() !== ''),
      rating: rating,
      review_count: reviewCount,
      google_maps_url: place.googleMapsUri || '',
      business_status: place.businessStatus || 'Unknown',
      category: place.types ? place.types[0] : 'Unknown',
      priority_tier: tier
    });
  }
}

// Sort by tier then review count ascending
scored.sort((a, b) => {
  if (a.priority_tier !== b.priority_tier) return a.priority_tier - b.priority_tier;
  return a.review_count - b.review_count;
});

// Cap at 20
scored = scored.slice(0, 20);

const summary = {
  keyword: filters.keyword,
  location: `${filters.city ? filters.city + ', ' : ''}${filters.country}`,
  total_found: places.length,
  total_after_filtering: scored.length,
  website_filter_applied: websiteFilter,
  min_rating_applied: minRating,
  max_review_count_applied: maxReviews
};

return [{
  json: {
    search_summary: summary,
    businesses: scored
  }
}];

// Runs ONCE - pulls all 20 businesses and their paired Serper results by index
const businesses = $('Split Out').all();
const searchItems = $input.all(); // output of Wait node, 1:1 paired with businesses by order

const batch = businesses.map((b, i) => {
  const business = b.json;
  const searchResults = (searchItems[i]?.json?.organic || []).slice(0, 5).map(r => ({
    title: (r.title || '').replace(/"/g, "'"),
    snippet: (r.snippet || '').replace(/"/g, "'"),
    link: r.link || ''
  }));
  return {
    id: business.place_id || String(i), // stable id for re-matching later
    name: business.name,
    address: business.address,
    website: business.website || 'Not listed',
    search_results: searchResults
  };
});

const prompt = `You are a data extraction specialist. For EACH business in the list below, find real, verifiable contact information using ONLY the search results provided for that business. Never invent or guess.

Businesses:
${JSON.stringify(batch, null, 2)}

Return ONLY a valid JSON array (no markdown, no backticks), with exactly one object per business, in this exact shape, using the same "id" you were given:
[
  {
    "id": "same id as input",
    "owner_name": "owner or founder name if explicitly mentioned, or Not found",
    "email": "a real email address if explicitly shown, or Not found",
    "instagram": "Instagram handle or URL if found, or Not found",
    "facebook": "Facebook page URL if found, or Not found",
    "linkedin": "LinkedIn company or owner page if found, or Not found",
    "additional_notes": "any other relevant contact detail or business info found, or empty string"
  }
]`;

return {
  json: {
    prompt: prompt,
    businesses: businesses.map(b => b.json) // carried forward for the merge step
  }
};

const raw = $input.item.json.candidates[0].content.parts[0].text;

let enriched;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  enriched = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Gemini batch response was not valid JSON: ' + e.message);
}
const businesses = $('Build Enrichment Prompt').item.json.businesses;

const enrichedById = new Map(enriched.map(e => [String(e.id), e]));

return businesses.map((business, i) => {
  const id = business.place_id || String(i);
  const match = enrichedById.get(String(id)) || {};
  return {
    json: {
      ...business,
      owner_name: match.owner_name || 'Not found',
      email: match.email || 'Not found',
      instagram: match.instagram || 'Not found',
      facebook: match.facebook || 'Not found',
      linkedin: match.linkedin || 'Not found',
      additional_notes: match.additional_notes || ''
    }
  };
});

const body = $input.item.json.body;

const country = body.country || '';
const city = body.city || '';
const keyword = body.keyword || '';
const newOrOld = body.newOrOld || 'any';
const websiteFilter = body.websiteFilter || 'both';
const minRating = parseFloat(body.minRating) || 0;
const maxReviews = parseInt(body.maxReviews) || 9999;
const minReviews = parseInt(body.minReviews) || 0;

// Build multiple search queries to maximise result pool
// When no city provided, we search country-level which Google
// handles via textQuery — it will find best matches nationally
const searches = [];

if (city && city.trim() !== '') {
  // City provided — search that city specifically
  searches.push(`${keyword} in ${city}, ${country}`);
  // Also search surrounding area for more results
  searches.push(`${keyword} near ${city}, ${country}`);
} else {
  // No city — search country level
  // Google Places handles this and returns results from
  // major populated areas automatically
  searches.push(`${keyword} in ${country}`);
  searches.push(`best ${keyword} ${country}`);
  searches.push(`local ${keyword} ${country}`);
}

return [{
  json: {
    // Primary search text (used by Places API)
    searchText: searches[0],
    // All search variants (for retry logic)
    searchVariants: searches,
    currentVariantIndex: 0,
    country: country,
    city: city,
    keyword: keyword,
    newOrOld: newOrOld,
    websiteFilter: websiteFilter,
    minRating: minRating,
    maxReviews: maxReviews,
    minReviews: minReviews,
    allPlaces: []
  }
}];
